python3 -c "
import subprocess, re
# Find the page where Limitations starts
result = subprocess.run(['pdftotext', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
pages = text.split('\x0c')
for i, page in enumerate(pages):
    if 'Limitations' in page and i > 3:
        print(f'Limitations starts on page {i+1}')
        break
for i, page in enumerate(pages):
    if 'References' in page and '\\bibliography' not in page and i > 3:
        # Check if it's the references section header
        lines = page.strip().split('\n')
        for line in lines:
            if line.strip() == 'References' or re.match(r'^References\s*$', line.strip()):
                print(f'References header on page {i+1}')
                break
" 2>&1
